    "I'm from England. But I live in Estonia.": "Я из Англии. Но живу в Эстонии.",
    "And Anna?": "А Анна?",
    "And I'm from Estonia. I'm Estonian!": "А я из Эстонии. Я эстонка!",
    "Where are you from?": "Откуда ты?",
    "Where are you from? (polite)": "Откуда вы? (вежливо)",
