    "from America": "из Америки",
    "from Russia": "из России",
    "{Pärit} always takes the from-form: {Ma olen pärit Eestist}, never {Ma olen pärit Eesti}.": "{Pärit} всегда требует формы со значением «из»: {Ma olen pärit Eestist}, и никогда не {Ma olen pärit Eesti}.",
    "A country whose name ends in -maa says \"from\" with -lt, and the others with -st. Learn each one whole for now.": "Если название страны оканчивается на -maa, «из» выражается окончанием -lt, а у остальных окончанием -st. Пока учите каждую форму целиком.",
    "{Aga} is but: {Ma olen pärit Inglismaalt, aga ma elan Eestis}.": "{Aga} значит «но»: {Ma olen pärit Inglismaalt, aga ma elan Eestis}.",
    "A country has a capital letter and the person from it doesn't: {Eesti}, but {eestlane}.": "Страна пишется с заглавной буквы, а её житель нет: {Eesti}, но {eestlane}.",
    "Country": "Страна",
    "From there": "Оттуда",
