    "I'm from England.": "Я из Англии.",
    "Ask a stranger, politely, where they're from.": "Вежливо спросите незнакомого человека, откуда он.",
    "Say you're from England, but you live in Estonia.": "Скажите, что вы из Англии, но живёте в Эстонии.",
    "I'm from England, but I live in Estonia.": "Я из Англии, но живу в Эстонии.",
    "Anna, where are you from?": "Анна, откуда ты?",
