    "My friend is from Finland too. But he lives in Sweden.": "Мой друг тоже из Финляндии. Но он живёт в Швеции.",
    "And you? Are you Estonian?": "А ты? Ты эстонец?",
    "Yes. But my teacher is from Latvia. She's Latvian.": "Да. Но моя учительница из Латвии. Она латышка.",
