    "{Saksamaa} is a -maa country, like {Inglismaa}: from Germany is {Saksamaalt}, never with -st.": "{Saksamaa} это страна на -maa, как и {Inglismaa}: «из Германии» будет {Saksamaalt}, никогда не с -st.",
    "Say you're from Finland, or where you're really from.": "Скажите, что вы из Финляндии, или откуда вы на самом деле.",
    "I'm from Finland.": "Я из Финляндии.",
    "Say a friend of yours lives in Sweden.": "Скажите, что ваш друг живёт в Швеции.",
    "My friend lives in Sweden.": "Мой друг живёт в Швеции.",
    "Say you're from Germany and you're German.": "Скажите, что вы из Германии и что вы немец.",
    "I'm from Germany. I'm German.": "Я из Германии. Я немец.",
