    "Say a little, and that you're learning it.": "Скажите «немного» и что вы его учите.",
    "Say which languages you speak.": "Скажите, на каких языках вы говорите.",
    "I speak English and a little Estonian.": "Я говорю по-английски и немного по-эстонски.",
    "Ask somebody whether they speak Russian.": "Спросите кого-нибудь, говорит ли он по-русски.",
    "Do you speak Russian?": "Ты говоришь по-русски?",
    "Tom, do you live in Tallinn?": "Том, ты живёшь в Таллине?",
    "No, I don't live in Tallinn. I live in Tartu.": "Нет, я не живу в Таллине. Я живу в Тарту.",
    "A little. I don't speak it well yet.": "Немного. Я ещё не очень хорошо говорю.",
    "But you're learning!": "Но ты же учишь!",
    "Yes, of course!": "Да, конечно!",
    "live, after {ei}": "жить, после {ei}",
    "speak, after {ei}": "говорить, после {ei}",
