    "of course": "конечно",
    "You've been doing this since lesson 6, where {olen} became {ei ole}.": "Вы делаете это с урока 6, где {olen} стало {ei ole}.",
    "Say no, you don't live in Tallinn. You live in Tartu.": "Скажите, что нет, вы не живёте в Таллине. Вы живёте в Тарту.",
    "Do you live in Tallinn?": "Ты живёшь в Таллине?",
    "Say no, you don't.": "Скажите, что нет.",
