    "Say you don't speak Estonian well yet.": "Скажите, что вы ещё не очень хорошо говорите по-эстонски.",
    "I don't speak Estonian well yet.": "Я ещё не очень хорошо говорю по-эстонски.",
    "Say yes, of course.": "Скажите «да, конечно».",
    "Are you learning Estonian?": "Ты учишь эстонский?",
    "Tom, what's your phone number?": "Том, какой у тебя номер телефона?",
    "Five, two, zero, one, three, seven, eight.": "Пять, два, ноль, один, три, семь, восемь.",
    "Slower, please!": "Помедленнее, пожалуйста!",
    "Five. Two. Zero. One. Three. Seven. Eight.": "Пять. Два. Ноль. Один. Три. Семь. Восемь.",
    "Thanks! Mine is five, four, nine, six, zero, one, two.": "Спасибо! Мой: пять, четыре, девять, шесть, ноль, один, два.",
