    "number": "номер",
    "phone number": "номер телефона",
    "Ten words, and a phone number is said one digit at a time.": "Десять слов, а номер телефона называют по одной цифре.",
    "{Kuus}, six, has a long uu. Hold it, or it turns into another word.": "{Kuus}, шесть, имеет долгое uu. Тяните его, иначе получится другое слово.",
    "{Telefoninumber} is {telefon} and {number} written as one word. Estonian builds long words by putting short ones together, and you'll see it everywhere.": "{Telefoninumber} это {telefon} и {number}, написанные одним словом. Эстонский строит длинные слова, соединяя короткие, и вы увидите это повсюду.",
    "{Kaheksa} and {üheksa} are eight and nine, and they sound alike. Listen to the first sound.": "{Kaheksa} и {üheksa}: восемь и девять, и звучат они похоже. Слушайте первый звук.",
    "{Mis su telefoninumber on?} is built just like {Mis su nimi on?}": "{Mis su telefoninumber on?} строится так же, как {Mis su nimi on?}",
    "Number": "Число",
    "Say a phone number, one digit at a time. Any one will do.": "Назовите номер телефона по одной цифре. Подойдёт любой.",
    "What's your phone number?": "Какой у тебя номер телефона?",
    "Count from one to ten.": "Посчитайте от одного до десяти.",
    "One, two, three, four, five, six, seven, eight, nine, ten.": "Один, два, три, четыре, пять, шесть, семь, восемь, девять, десять.",
    "Ask somebody for their phone number.": "Спросите у кого-нибудь номер телефона.",
    "Tom, how old are you?": "Том, сколько тебе лет?",
