    "A double letter often goes single before the ending: {kapp} gives {kapis}, {kott} gives {kotis}.": "Двойная буква перед окончанием часто становится одинарной: {kapp} даёт {kapis}, {kott} даёт {kotis}.",
    "{Külmkapp} is a {kapp} that is cold, and it changes like {kapp}: {kapis}, {külmkapis}.": "{Külmkapp} это холодный шкаф, {kapp}, и меняется он как {kapp}: {kapis}, {külmkapis}.",
