    "far, far away": "далеко, вдали",
    "Directions are three words and a {siis}: {otse}, {vasakule}, {paremale}.": "Чтобы объяснить дорогу, хватит трёх слов и {siis}: {otse}, {vasakule}, {paremale}.",
    "If the directions come too fast, you have the line for it: {Aeglasemalt, palun}. Most people will point as well.": "Если дорогу объясняют слишком быстро, у вас есть нужная фраза: {Aeglasemalt, palun}. Большинство людей ещё и покажут рукой.",
    "{Vasakule} and {paremale} are where to, like {koju}: they point the way to turn.": "{Vasakule} и {paremale} отвечают на «куда», как {koju}: они показывают, куда повернуть.",
    "{Lähedal} and {kaugel} say where something is: near, or far.": "{Lähedal} и {kaugel} говорят, где что-то находится: близко или далеко.",
    "Long words are often two short ones joined: bus and station make {bussijaam}.": "Длинные слова часто состоят из двух коротких: «автобус» и «станция» дают {bussijaam}.",
    "turn left": "поверните налево",
