    "Walking is {jalgsi}, a word of its own. There is no vehicle, so there is no -ga.": "Пешком будет {jalgsi}, отдельное слово. Транспорта нет, поэтому нет и -ga.",
    "{Ülikool} is a big {kool}, and the ending goes on it the same way: {ülikoolis}.": "{Ülikool} это большая школа, {kool}, и окончание ставится на него так же: {ülikoolis}.",
    "With its ending": "С окончанием",
