    "By bus. Thank you! Goodbye!": "На автобусе. Спасибо! До свидания!",
    "A whole conversation with a stranger, made only of what this part taught.": "Целый разговор с незнакомым человеком, только из того, чему научила эта часть.",
    "You don't have to understand every word of the directions. Catch {otse}, {vasakule} and {paremale}, and the rest is pointing.": "Не обязательно понимать каждое слово, когда вам объясняют дорогу. Уловите {otse}, {vasakule} и {paremale}, а остальное покажут рукой.",
    "Notice how Tom asks: {Vabandust} first, then the question. That's all the politeness it needs.": "Обратите внимание, как спрашивает Том: сначала {Vabandust}, потом вопрос. Больше вежливости и не нужно.",
    "Stop a stranger and ask where the bus station is.": "Остановите незнакомого человека и спросите, где автовокзал.",
    "Say you're going to Tartu.": "Скажите, что едете в Тарту.",
