    "Describing words come in pairs, so learn them as opposites, as in lesson 36: {pikk} and {lühike}.": "Описательные слова идут парами, поэтому учите их как противоположности, как в уроке 36: {pikk} и {lühike}.",
    "{Lihtne} and {kerge} both mean easy. {Lihtne} is simple to do; {kerge} is also light to carry.": "{Lihtne} и {kerge} оба значат «лёгкий». {Lihtne} значит «простой в деле»; {kerge} ещё и «лёгкий, чтобы нести».",
