    "Four of the colors end the same way: {punane}, {sinine}, {roheline}, {kollane}. Say them aloud as a list.": "Четыре цвета кончаются одинаково: {punane}, {sinine}, {roheline}, {kollane}. Произнесите их вслух списком.",
