    "Hello! I need a hat. It's really cold today!": "Здравствуйте! Мне нужна шапка. Сегодня очень холодно!",
    "Yes, it's cold outside. What color?": "Да, на улице холодно. Какого цвета?",
    "Gray or black.": "Серая или чёрная.",
    "This gray hat is good. And cheap!": "Эта серая шапка хорошая. И дешёвая!",
    "Ten euros.": "Десять евро.",
    "Very good. By card, please.": "Очень хорошо. Картой, пожалуйста.",
    "A whole visit to a shop, made only of what this part and the ones before it taught.": "Целый поход в магазин, только из того, чему научили эта часть и предыдущие.",
    "You don't need to describe the thing perfectly. What you need, and a color, is enough to be shown it.": "Не нужно описывать вещь идеально. Того, что вам нужно, и цвета хватит, чтобы вам её показали.",
    "Tom opens with the weather and the shop assistant picks it up. That's how a lot of small talk in Estonia starts.": "Том начинает с погоды, и продавец подхватывает. Так в Эстонии начинаются многие короткие разговоры.",
    "Say blue.": "Скажите: синяя.",
    "Blue.": "Синяя.",
    "Say it's cheap and nice.": "Скажите, что она дешёвая и красивая.",
    "It's cheap and nice.": "Она дешёвая и красивая.",
    "Say you need a hat.": "Скажите, что вам нужна шапка.",
    "I need a hat.": "Мне нужна шапка.",
    "Say gray or black.": "Скажите: серая или чёрная.",
    "Yes, it's cold outside! What color?": "Да, на улице холодно! Какого цвета?",
    "This gray hat is nice.": "Эта серая шапка красивая.",
    "Say very good, by card.": "Скажите: очень хорошо, картой.",
    "It's a cold day and you need a hat. The shop assistant speaks first.": "Холодный день, и вам нужна шапка. Продавец говорит первым.",
    "Tom, what are you doing tomorrow?": "Том, что ты делаешь завтра?",
    "Tomorrow I'm working. And on Saturday I'm going to Tartu.": "Завтра я работаю. А в субботу еду в Тарту.",
    "And next week?": "А на следующей неделе?",
    "I don't know. Maybe I'll be at home.": "Не знаю. Может быть, буду дома.",
    "I'm in Tallinn next week! Shall we meet up?": "Я на следующей неделе в Таллинне! Встретимся?",
    "Yes, definitely!": "Да, обязательно!",
    "next": "следующий",
    "next week": "на следующей неделе",
    "maybe": "может быть",
    "definitely, for sure": "обязательно, точно",
    "Let's meet up!": "Давай встретимся!",
    "Estonian has no future tense. The present and a word for when says it: {Homme ma töötan}, I'll work tomorrow.": "В эстонском нет будущего времени. Его выражают настоящее время и слово, которое говорит когда: {Homme ma töötan}, завтра я буду работать.",
    "The word for when often goes first, and the rest follows as in any sentence: {Homme ma töötan}.": "Слово, которое говорит когда, часто стоит первым, а остальное идёт как в любом предложении: {Homme ma töötan}.",
    "Say you're working tomorrow.": "Скажите, что завтра вы работаете.",
