    "Order a coffee.": "Замовте каву.",
    "Say yes, a cake too.": "Скажіть «так, і ще торт».",
    "Yes, a cake too.": "Так, і ще торт.",
    "A tea, please.": "Чай, будь ласка.",
    "Tom, what do you want to drink?": "Томе, що ти хочеш пити?",
    "I want coffee. And you?": "Я хочу кави. А ти?",
    "I'm having tea. And I want to eat a bun.": "Я буду чай. І я хочу з'їсти булочку.",
    "Do we have any milk?": "У нас є молоко?",
    "No, there's no milk. But there's water!": "Ні, молока немає. Але є вода!",
    "coffee, some coffee": "кава, трохи кави",
    "tea, some tea": "чай, трохи чаю",
    "water, some water": "вода, трохи води",
    "juice, some juice": "сік, трохи соку",
    "milk, some milk": "молоко, трохи молока",
    "a bun, some bread": "булочка, трохи хліба",
    "cake, some cake": "торт, трохи торта",
    "what, as the thing you do or want": "що, як те, що ви робите чи хочете",
    "You've been saying this ending since lesson 11: {eesti keelt}, {raamatut}, {kaks aastat}. And {Mida sa teed?}: {mida} is {mis} with the same ending, because it's the thing you do.": "Ви кажете це закінчення з уроку 11: {eesti keelt}, {raamatut}, {kaks aastat}. І {Mida sa teed?}: {mida} це {mis} із тим самим закінченням, бо це те, що ви робите.",
    "Say you want tea.": "Скажіть, що ви хочете чаю.",
    "What do you want to drink?": "Що ти хочеш пити?",
    "I want tea.": "Я хочу чаю.",
    "Say you're drinking water.": "Скажіть, що ви п'єте воду.",
    "I'm drinking water.": "Я п'ю воду.",
    "Say no, there's no milk.": "Скажіть «ні, молока немає».",
    "No, there's no milk.": "Ні, молока немає.",
    "Say you want to eat cake.": "Скажіть, що ви хочете з'їсти торт.",
    "I want to eat cake.": "Я хочу з'їсти торт.",
    "Two coffees, please.": "Дві кави, будь ласка.",
    "And a glass of water.": "І склянку води.",
    "Two coffees and a glass of water. Anything else?": "Дві кави й склянка води. Щось іще?",
    "Yes, three buns.": "Так, три булочки.",
    "Three buns? Here you are!": "Три булочки? Прошу!",
    "And one more cup of tea!": "І ще одну чашку чаю!",
    "cup": "чашка",
    "cups, after a number": "чашки, після числа",
    "glasses, after a number": "склянки, після числа",
    "One": "Один",
    "Order two coffees.": "Замовте дві кави.",
    "A glass of water, please.": "Склянку води, будь ласка.",
    "One more cup of tea, please.": "Ще одну чашку чаю, будь ласка.",
    "What do you eat in the evening?": "Що ти їси ввечері?",
    "I eat fish and potatoes.": "Я їм рибу й картоплю.",
    "I eat meat. Do you want some bread?": "Я їм м'ясо. Хочеш хліба?",
