    "some wine, a glass of": "трохи вина, келих",
    "{Leib} is the dark rye bread Estonians eat every day. White bread is {sai}, from lesson 24.": "{Leib} це темний житній хліб, який естонці їдять щодня. Білий хліб це {sai}, з уроку 24.",
    "{Toit} is food in general, the word on a menu or a shop sign.": "{Toit} це їжа загалом, слово з меню чи з вивіски крамниці.",
    "Say what you eat.": "Скажіть, що ви їсте.",
    "Say you'd like bread and cheese.": "Скажіть, що вам хотілося б хліба й сиру.",
    "I'd like bread and cheese.": "Мені хотілося б хліба й сиру.",
    "Offer somebody soup.": "Запропонуйте комусь суп.",
    "Do you want some soup?": "Хочеш супу?",
    "Excuse me, how much is this?": "Перепрошую, скільки це коштує?",
    "Three euros.": "Три євро.",
    "And the cake?": "А торт?",
    "The cake is four euros fifty.": "Торт коштує чотири євро п'ятдесят.",
    "Fine. One cake and one coffee, please.": "Добре. Один торт і одну каву, будь ласка.",
    "Seven fifty altogether. By card?": "Разом сім п'ятдесят. Карткою?",
    "Yes, by card.": "Так, карткою.",
    "How much does it cost?": "Скільки це коштує?",
