    "cent": "цент",
    "cents, after a number": "центи, після числа",
    "altogether, in total": "разом, загалом",
    "by card": "карткою",
    "in cash": "готівкою",
    "One euro is {üks euro}. From two up it's {eurot}, so listen for the number first.": "Одне євро це {üks euro}. Від двох і більше це {eurot}, тож спершу слухайте число.",
    "People often drop the cents word: {neli eurot viiskümmend}.": "Слово для центів часто пропускають: {neli eurot viiskümmend}.",
    "Price": "Ціна",
    "Ask how much something costs.": "Запитайте, скільки щось коштує.",
    "Say yes, by card.": "Скажіть: так, карткою.",
    "Five euros altogether. By card?": "Разом п'ять євро. Карткою?",
    "Say no, you'll pay cash.": "Скажіть, що ні, заплатите готівкою.",
    "By card?": "Карткою?",
    "No, cash.": "Ні, готівкою.",
    "Tom, do you like coffee?": "Томе, тобі подобається кава?",
