    "I don't like coffee. I like tea.": "Мені не подобається кава. Мені подобається чай.",
    "And Jaan? Does he like tea?": "А Яан? Йому подобається чай?",
    "No. He only likes beer!": "Ні. Йому подобається тільки пиво!",
    "to you": "тобі",
    "to him, to her": "йому, їй",
