    "Do you like coffee?": "Тобі подобається кава?",
    "Yes, I like coffee.": "Так, мені подобається кава.",
    "Say you don't like beer.": "Скажіть, що вам не подобається пиво.",
    "I don't like beer.": "Мені не подобається пиво.",
    "Ask a friend whether they like tea.": "Запитайте друга, чи подобається йому чай.",
    "Do you like tea?": "Тобі подобається чай?",
    "Good evening! What would you like?": "Добрий вечір! Що ви бажаєте?",
    "Hello! A coffee and a tea, please.": "Добрий день! Каву і чай, будь ласка.",
    "Yes, two cakes. I love cake!": "Так, два тістечка. Я обожнюю тістечка!",
    "Two cakes. Here you are!": "Два тістечка. Прошу!",
    "Excuse me, how much is it?": "Перепрошую, скільки це коштує?",
    "Later.": "Пізніше.",
    "Nine euros altogether.": "Разом дев'ять євро.",
    "A whole evening at a café, made only of what this part taught.": "Цілий вечір у кафе, лише з того, чого навчила ця частина.",
    "If the price comes too fast, you already have the line for it: {Aeglasemalt, palun}.": "Якщо ціну назвуть надто швидко, у вас уже є потрібна фраза: {Aeglasemalt, palun}.",
    "Notice how little you need: what you want, how many, and how you'll pay.": "Зверніть увагу, як мало потрібно: що ви хочете, скільки і як платитимете.",
    "Order a coffee and a cake.": "Замовте каву і тістечко.",
    "A coffee and a cake, please.": "Каву і тістечко, будь ласка.",
    "Say you'll pay by card.": "Скажіть, що заплатите карткою.",
    "Six euros altogether.": "Разом шість євро.",
    "Say you like tea, but not coffee.": "Скажіть, що вам подобається чай, але не кава.",
    "I like tea, but not coffee.": "Мені подобається чай, але не кава.",
    "Yes, a glass of water too.": "Так, і склянку води теж.",
    "Ask how much it is.": "Запитайте, скільки це коштує.",
    "Here you are!": "Прошу!",
    "Thanks! How much is it?": "Дякую! Скільки це коштує?",
    "You're at a café counter with a friend. The waiter, Liis, speaks first.": "Ви з другом біля стійки в кафе. Першою говорить офіціантка Ліїс.",
    "And where's the kitchen?": "А де кухня?",
