    "room": "кімната",
    "bed": "ліжко",
    "{Tuba} is a room you live in. The kitchen is never a {tuba}, it's {köök}.": "{Tuba} це кімната, в якій живуть. Кухня ніколи не {tuba}, це {köök}.",
    "{Siin} is here, near you, and {seal} is there, further off. Point as you say it.": "{Siin} означає «тут», поруч із вами, а {seal} «там», далі. Показуйте рукою, коли кажете.",
