    "from work": "з роботи",
    "in the shop": "у магазині",
    "to the shop": "до магазину",
    "from the shop": "з магазину",
    "Estonian asks about a place three ways, and every place answers all three.": "В естонській про місце питають трьома способами, і кожне місце має всі три відповіді.",
    "{Koju} and {poodi} are where to, never where. {Ma olen kodus}, but {Ma lähen koju}.": "{Koju} і {poodi} відповідають на «куди», а не на «де». {Ma olen kodus}, але {Ma lähen koju}.",
    "Learn each place as its set of three, and say them aloud together: {kodus, koju, kodust}.": "Вивчайте кожне місце трійкою і промовляйте всі три вголос разом: {kodus, koju, kodust}.",
