    "Say your computer is in the living room.": "Скажіть, що ваш комп'ютер у вітальні.",
    "My computer is in the living room.": "Мій комп'ютер у вітальні.",
    "Ask where the key is.": "Запитайте, де ключ.",
    "Where's the key?": "Де ключ?",
    "Excuse me, where's the pharmacy?": "Перепрошую, де аптека?",
    "The pharmacy? Straight on, then left.": "Аптека? Прямо, потім ліворуч.",
    "Is it far?": "Це далеко?",
    "No, it's close.": "Ні, близько.",
    "And where's the bus station?": "А де автовокзал?",
    "The bus station is far. Straight on, keep going, then right.": "Автовокзал далеко. Прямо, весь час прямо, потім праворуч.",
    "pharmacy": "аптека",
    "bus station": "автовокзал",
    "straight on": "прямо",
    "to the left, turn left": "ліворуч, поверніть ліворуч",
    "to the right, turn right": "праворуч, поверніть праворуч",
    "near, close by": "поруч, близько",
    "far, far away": "далеко, вдалині",
    "Directions are three words and a {siis}: {otse}, {vasakule}, {paremale}.": "Щоб пояснити дорогу, досить трьох слів і {siis}: {otse}, {vasakule}, {paremale}.",
    "If the directions come too fast, you have the line for it: {Aeglasemalt, palun}. Most people will point as well.": "Якщо дорогу пояснюють надто швидко, у вас є потрібна фраза: {Aeglasemalt, palun}. Більшість людей ще й покаже рукою.",
    "{Vasakule} and {paremale} are where to, like {koju}: they point the way to turn.": "{Vasakule} і {paremale} відповідають на «куди», як {koju}: вони показують, куди повернути.",
    "{Lähedal} and {kaugel} say where something is: near, or far.": "{Lähedal} і {kaugel} кажуть, де щось є: близько чи далеко.",
    "Long words are often two short ones joined: bus and station make {bussijaam}.": "Довгі слова часто складаються з двох коротких: «автобус» і «станція» дають {bussijaam}.",
    "turn left": "поверніть ліворуч",
    "turn right": "поверніть праворуч",
    "it's near": "це близько",
    "it's far": "це далеко",
    "Ask a stranger where the pharmacy is.": "Запитайте незнайомця, де аптека.",
    "Say no, it's near.": "Скажіть, що ні, це близько.",
    "No, it's near.": "Ні, це близько.",
    "Say straight on and then right.": "Скажіть: прямо, а потім праворуч.",
    "Where's the hospital?": "Де лікарня?",
    "Straight on and then right.": "Прямо, а потім праворуч.",
    "Tom, how do you get to work?": "Томе, як ти добираєшся на роботу?",
    "By bus. And you?": "Автобусом. А ти?",
    "I go by tram. But tomorrow I'm going to Tartu.": "Я їжджу трамваєм. Але завтра я їду до Тарту.",
    "By train or by bus?": "Поїздом чи автобусом?",
    "By train. The ticket's nine euros.": "Поїздом. Квиток коштує дев'ять євро.",
    "Nice!": "Чудово!",
