    "by taxi": "таксі",
    "Walking is {jalgsi}, a word of its own. There is no vehicle, so there is no -ga.": "Пішки буде {jalgsi}, окреме слово. Транспорту немає, тому немає і -ga.",
    "{Ülikool} is a big {kool}, and the ending goes on it the same way: {ülikoolis}.": "{Ülikool} це велика школа, {kool}, і закінчення додається до нього так само: {ülikoolis}.",
    "With its ending": "Із закінченням",
    "Say you work at a school, or anywhere you like.": "Скажіть, що працюєте в школі або будь-де.",
    "I work at a school.": "Я працюю в школі.",
    "Say by car.": "Скажіть «машиною».",
