    "Ask where the hotel is.": "Запитайте, де готель.",
    "Where's the hotel?": "Де готель?",
    "Excuse me, where's the bus station?": "Перепрошую, де автовокзал?",
    "The bus station? Straight on and then right.": "Автовокзал? Прямо, а потім праворуч.",
    "No, it's close. Where are you going?": "Ні, близько. Куди ви їдете?",
    "I'm going to Tartu.": "Я їду до Тарту.",
