    "By bus. Thank you! Goodbye!": "Автобусом. Дякую! До побачення!",
    "A whole conversation with a stranger, made only of what this part taught.": "Ціла розмова з незнайомою людиною, лише з того, чого навчила ця частина.",
    "You don't have to understand every word of the directions. Catch {otse}, {vasakule} and {paremale}, and the rest is pointing.": "Не обов'язково розуміти кожне слово, коли вам пояснюють дорогу. Вловіть {otse}, {vasakule} і {paremale}, а решту покажуть рукою.",
    "Notice how Tom asks: {Vabandust} first, then the question. That's all the politeness it needs.": "Зверніть увагу, як питає Том: спочатку {Vabandust}, потім питання. Більше ввічливості й не треба.",
    "Stop a stranger and ask where the bus station is.": "Зупиніть незнайому людину й запитайте, де автовокзал.",
    "Say you're going to Tartu.": "Скажіть, що їдете до Тарту.",
    "Say no, by train.": "Скажіть: ні, поїздом.",
    "By bus?": "Автобусом?",
    "No, by train.": "Ні, поїздом.",
    "Yes?": "Так?",
    "Ask whether it's far.": "Запитайте, чи це далеко.",
    "You're in town and need the pharmacy. Stop somebody and ask. They answer first in Estonian.": "Ви в місті, і вам потрібна аптека. Зупиніть когось і запитайте. Спочатку вам відповідають естонською.",
    "No, it's small. But it's nice.": "Ні, маленька. Але гарна.",
    "And the kitchen?": "А кухня?",
