    "Most of these come in pairs, so learn them as pairs and say them aloud together: {suur, väike}.": "Більшість із них ідуть парами, тож вивчайте їх парами й вимовляйте вголос разом: {suur, väike}.",
    "And its opposite": "І його протилежність",
    "Say no, it's small, but nice.": "Скажіть: ні, маленька, але гарна.",
    "No, it's small, but nice.": "Ні, маленька, але гарна.",
