    "Ask {Mis värvi?} and answer with the color, as it is: {Must}.": "Запитайте {Mis värvi?} і відповідайте назвою кольору без змін: {Must}.",
    "Four of the colors end the same way: {punane}, {sinine}, {roheline}, {kollane}. Say them aloud as a list.": "Чотири кольори закінчуються однаково: {punane}, {sinine}, {roheline}, {kollane}. Вимовте їх уголос списком.",
