    "You don't need to describe the thing perfectly. What you need, and a color, is enough to be shown it.": "Не треба описувати річ ідеально. Того, що вам потрібно, і кольору досить, щоб вам її показали.",
    "Tom opens with the weather and the shop assistant picks it up. That's how a lot of small talk in Estonia starts.": "Том починає з погоди, і продавець підхоплює. Так в Естонії починається чимало коротких розмов.",
